"""Printable document adapter; escapes all external text."""
from html import escape
from erp.shared.domain import validation as cinema

def report(close):
    e=lambda v:escape(str(v));money=lambda v:f'Bs {v:,.2f}'
    detail=close.get('detail',{});moves=detail.get('movements',[])
    rows=''.join(f'<tr><td>{e(m["at"][11:19])}</td><td>{"Ingreso" if m["direction"]=="in" else "Egreso"}</td><td>{e(m["reason"])}{(" · ANULADO: "+e(m.get("voidReason",""))+" · "+e(m.get("voidBy",""))) if m.get("voided") else ""}</td><td>{e(m["reference"])}</td><td>{money(m["total"])}</td></tr>' for m in moves)
    sales=''.join(f'<tr><td>{e(s["at"][11:19])}</td><td>{e(s["label"])}</td><td>{s["quantity"]}</td><td>{money(s["total"])}</td></tr>' for s in detail.get('sales',[]))
    return f'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cierre {e(close['id'])}</title><style>body{{font:14px Arial;color:#172b3a;max-width:1000px;margin:40px auto;padding:24px}}header{{border-bottom:3px solid #172b3a;padding-bottom:24px}}h1{{font-size:32px}}.metrics{{display:flex;gap:14px;flex-wrap:wrap;margin:30px 0}}.metrics div{{flex:1;background:#f0f4f6;padding:18px;min-width:130px}}strong{{display:block;font-size:22px;margin-top:10px}}table{{width:100%;border-collapse:collapse;margin:20px 0}}td,th{{text-align:left;border-bottom:1px solid #d5dfe5;padding:12px;font-size:12px}}h2{{margin-top:35px}}.formula{{padding:18px;border:1px solid #ccd6dd}}button{{padding:12px 22px}}@media print{{button{{display:none}}body{{margin:0;padding:0}}tr{{break-inside:avoid}}thead{{display:table-header-group}}@page{{size:A4;margin:15mm}}}}</style><link rel="stylesheet" href="/reports.css"><button onclick="window.print()">Imprimir reporte / Guardar PDF</button><header><p>UNIVERSAL · CONTROL DE CAJA</p><h1>Cierre diario de {e({'ticketing':'boletería','candy':'Candy bar'}.get(close.get('area'),'caja'))}</h1><p>{e(close['branch'])} · {e(close['day'])} · Responsable: {e(close['user'])}</p><small>Folio {e(close['id'])} · Estado: {e(close['status'])}</small></header><div class="metrics"><div>Ventas<strong>{money(detail.get('salesTotal',close['expected']))}</strong></div><div>Otros ingresos<strong>{money(detail.get('incomeTotal',0))}</strong></div><div>Egresos<strong>{money(detail.get('expenseTotal',0))}</strong></div></div><p class="formula">Saldo esperado = ventas + otros ingresos − egresos. Los ingresos adicionales no se cuentan como ventas.</p><div class="metrics"><div>Esperado en caja<strong>{money(close['expected'])}</strong></div><div>Físico verificado / declarado<strong>{money(close['physical'])}</strong></div><div>Diferencia<strong>{money(close['difference'])}</strong></div></div><p>Físico declarado al cerrar: {money(close.get('declaredPhysical',close['physical']))}. Diferencia positiva: sobrante; negativa: faltante; cero: caja conciliada.</p><p>Operaciones de venta: {detail.get('transactions','—')} · Unidades / boletos: {detail.get('quantity','—')} · Personas admitidas (boletería): {detail.get('people','—')}</p><h2>Ingresos y egresos</h2><table><thead><tr><th>Hora</th><th>Tipo</th><th>Motivo</th><th>Referencia</th><th>BOB</th></tr></thead><tbody>{rows or '<tr><td colspan="5">Sin movimientos adicionales</td></tr>'}</tbody></table><h2>Detalle de ventas</h2><table><thead><tr><th>Hora</th><th>Concepto / función</th><th>Cantidad</th><th>Importe</th></tr></thead><tbody>{sales or '<tr><td colspan="4">Sin detalle de ventas disponible</td></tr>'}</tbody></table><h2>Entrega y validación</h2><p>Observaciones del cajero: {e(close.get('cashierNote',close.get('note','')) or 'Sin observaciones')}</p><p>Revisión contable: {e(close.get('note','') if close.get('reviewer') else 'Pendiente')}<br>Revisado por: {e(close.get('reviewer','—'))}</p><p>Firma del cajero: _____________________ &nbsp; Firma de Contabilidad: _____________________</p><small>Las ventas anticipadas se incluyen en el día del cobro. El cierre bloquea ventas y movimientos hasta una nueva apertura de caja. Contabilidad confirma cuando la diferencia es cero.</small></html>'''.encode('utf-8')
